#include <iostream>

int main() {
    int next = 41;  // the next deli ticket to hand out

    // Risky: const int pair = next++ + next++;
    // next changes twice in one expression.
    const int first = next++;
    const int second = next++;
    std::cout << "pair " << first << " + " << second << " = " << first + second << '\n';

    // Risky: const int code = next++ * 100 + next;
    // * groups first, but nothing says next++ runs before the last next is read.
    const int now = next++;
    const int code = now * 100 + next;
    std::cout << "code " << code << '\n';

    // Safe: next changes once and is used nowhere else in the statement.
    const int mine = next++;
    std::cout << "mine " << mine << ", next " << next << '\n';
    return 0;
}

