#include <iostream>

int main() {
    int lap = 7;  // the lap a runner starts next

    // Risky: const int both = lap++ + lap++;
    const int first = lap++;
    const int second = lap++;
    std::cout << "laps " << first << " + " << second << " = " << first + second << '\n';

    // Risky: const int tag = lap++ * 100 + lap;
    const int now = lap++;
    const int tag = now * 100 + lap;
    std::cout << "tag " << tag << '\n';

    // Safe: lap changes once and is used nowhere else in the statement.
    const int undo = lap--;
    std::cout << "undo " << undo << ", lap " << lap << '\n';
    return 0;
}
